@lru_cache(maxsize=6)
def carregar_png_bytes(nome: str) -> bytes:
    """Retorna PNG original; valida SHA-256 e dimensoes antes de usar."""
    if nome not in MANIFESTO:
        raise KeyError(f"Arte Arena desconhecida: {nome}")
    data = base64.b85decode(''.join(_PNG_ASCII85[nome]).encode('ascii'))
    dados = MANIFESTO[nome]
    if hashlib.sha256(data).hexdigest() != dados['sha256']:
        raise ValueError(f"Falha de integridade PNG Arena: {nome}")
    if data[:8] != b'\x89PNG\r\n\x1a\n' or data[12:16] != b'IHDR':
        raise ValueError(f"Assinatura PNG inválida: {nome}")
    w,h = struct.unpack('>II',data[16:24])
    if (w,h) != (dados['width'],dados['height']):
        raise ValueError(f"Dimensoes PNG inesperadas: {nome}")
    return data


def carregar_pixmap(nome: str, *, tamanho_fallback=(32, 32)):
    """Retorna (QPixmap, carregou_arte). Fallback opaco seguro se arte indisponivel.

    Chamar somente na thread grafica com QApplication ja criado.
    Nao modifica widgets de jogos ou temporizadores.
    """
    from PySide6.QtGui import QPixmap, QColor
    try:
        raw = carregar_png_bytes(nome)
        pm = QPixmap()
        if pm.loadFromData(raw, 'PNG') and not pm.isNull():
            return pm, True
    except (KeyError, ValueError, TypeError):
        pass
    largura = max(1, min(4096, int(tamanho_fallback[0])))
    altura = max(1, min(4096, int(tamanho_fallback[1])))
    fallback = QPixmap(largura, altura)
    fallback.fill(QColor('#071625'))
    return fallback, False
